Using the frozen Brief and approved skeleton, write a complete ExperimentalMusicSpec. Preserve the skeleton's identity and section plan while realizing concrete notes, rests, velocities and useful CC. Output only the complete spec JSON.


FROZEN BRIEF:
{
  "id": "l1-video-motif",
  "level": "L1",
  "title": "Discovery documentary motif",
  "purpose": "A restrained motif for the opening of a documentary scene where a scientist notices an unexpected pattern.",
  "duration_seconds": 20,
  "section_plan": [
    "observation: 4 bars",
    "realization: 4 bars"
  ],
  "style": [
    "minimal chamber",
    "modal",
    "cinematic restraint"
  ],
  "mood": [
    "curious",
    "precise",
    "quietly surprising"
  ],
  "must_include": [
    "motif transforms in the second section",
    "harmonic ambiguity resolves only partially"
  ],
  "must_avoid": [
    "trailer braams",
    "heroic cadence",
    "busy percussion"
  ],
  "instrument_roles": [
    "felt piano",
    "soft strings",
    "single pulse"
  ],
  "delivery": [
    "8 bars",
    "2 to 3 tracks",
    "clear section marker"
  ],
  "score_focus": [
    "motif identity",
    "development",
    "restraint"
  ],
  "mode_a": false
}

SKELETON:
{
  "title": "Discovery documentary motif",
  "tempo_map": [
    {
      "bar": 1,
      "bpm": 96
    }
  ],
  "key_map": [
    {
      "bar": 1,
      "key": "D dorian"
    }
  ],
  "sections": [
    {
      "id": "observation",
      "start_bar": 1,
      "bars": 4
    },
    {
      "id": "realization",
      "start_bar": 5,
      "bars": 4
    }
  ],
  "track_plan": [
    {
      "id": "felt_piano",
      "name": "Felt Piano",
      "role": "melody",
      "register": {
        "low": 48,
        "high": 84
      },
      "instrument_hint": "felt piano",
      "section_jobs": [
        {
          "section_id": "observation",
          "intent": "Introduce three-note motif D-F-E with gentle rhythm, leave space",
          "density": "sparse"
        },
        {
          "section_id": "realization",
          "intent": "Transform motif: invert contour and shift to G dorian color, vary rhythm",
          "density": "medium"
        }
      ]
    },
    {
      "id": "soft_strings",
      "name": "Soft Strings",
      "role": "harmony",
      "register": {
        "low": 52,
        "high": 76
      },
      "instrument_hint": "soft string pad",
      "section_jobs": [
        {
          "section_id": "observation",
          "intent": "Sustain Dm7 add9 pad with slow swell",
          "density": "sparse"
        },
        {
          "section_id": "realization",
          "intent": "Move to G/D then Em7, unresolved final chord",
          "density": "sparse"
        }
      ]
    },
    {
      "id": "single_pulse",
      "name": "Single Pulse",
      "role": "pulse",
      "register": {
        "low": 40,
        "high": 52
      },
      "instrument_hint": "soft felt piano or muted pulse",
      "section_jobs": [
        {
          "section_id": "observation",
          "intent": "Single soft pulse on beat 2 of each bar",
          "density": "sparse"
        },
        {
          "section_id": "realization",
          "intent": "Continue pulse with occasional off-beat",
          "density": "sparse"
        }
      ]
    }
  ],
  "motif_strategy": "Three-note motif D-F-E (ascending minor third then step down) introduced in piano; in realization, contour inverted to F-D-E and transposed, fragmented rhythm with rests.",
  "harmony_strategy": "D dorian mode; chords Dm7, G/D, Em7; avoid V-I, end on G/D with added 9th for partial resolution.",
  "groove_strategy": "Sparse quarter-note pulse on felt piano soft attack, with gaps; no percussion."
}

EXPERIMENTAL MUSIC SPEC SCHEMA:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://auto-studio.local/q0/experimental-music-spec.schema.json",
  "title": "ExperimentalMusicSpec",
  "type": "object",
  "additionalProperties": false,
  "required": ["title", "tempo_map", "key_map", "sections", "tracks"],
  "properties": {
    "title": {"type": "string", "minLength": 1, "maxLength": 120},
    "tempo_map": {"type": "array", "minItems": 1, "maxItems": 24, "items": {"$ref": "#/$defs/tempo_change"}},
    "key_map": {"type": "array", "minItems": 1, "maxItems": 24, "items": {"$ref": "#/$defs/key_change"}},
    "sections": {"type": "array", "minItems": 1, "maxItems": 24, "items": {"$ref": "#/$defs/section"}},
    "tracks": {"type": "array", "minItems": 1, "maxItems": 16, "items": {"$ref": "#/$defs/track"}}
  },
  "$defs": {
    "time_signature": {
      "type": "object", "additionalProperties": false,
      "required": ["numerator", "denominator"],
      "properties": {
        "numerator": {"type": "integer", "minimum": 1, "maximum": 32},
        "denominator": {"enum": [1, 2, 4, 8, 16, 32]}
      }
    },
    "tempo_change": {
      "type": "object", "additionalProperties": false,
      "required": ["bar", "bpm", "time_signature"],
      "properties": {
        "bar": {"type": "integer", "minimum": 1, "maximum": 1024},
        "bpm": {"type": "number", "minimum": 30, "maximum": 300},
        "time_signature": {"$ref": "#/$defs/time_signature"}
      }
    },
    "key_change": {
      "type": "object", "additionalProperties": false,
      "required": ["bar", "tonic", "mode"],
      "properties": {
        "bar": {"type": "integer", "minimum": 1, "maximum": 1024},
        "tonic": {"type": "string", "minLength": 1, "maxLength": 8},
        "mode": {"type": "string", "minLength": 1, "maxLength": 32}
      }
    },
    "section": {
      "type": "object", "additionalProperties": false,
      "required": ["id", "label", "start_bar", "length_bars", "intent"],
      "properties": {
        "id": {"type": "string", "pattern": "^[a-z0-9][a-z0-9_-]{0,47}$"},
        "label": {"type": "string", "minLength": 1, "maxLength": 80},
        "start_bar": {"type": "integer", "minimum": 1, "maximum": 1024},
        "length_bars": {"type": "integer", "minimum": 1, "maximum": 128},
        "intent": {"type": "string", "minLength": 1, "maxLength": 240}
      }
    },
    "register": {
      "type": "object", "additionalProperties": false,
      "required": ["low", "high"],
      "properties": {
        "low": {"type": "integer", "minimum": 0, "maximum": 127},
        "high": {"type": "integer", "minimum": 0, "maximum": 127}
      }
    },
    "note": {
      "type": "object", "additionalProperties": false,
      "required": ["beat", "duration", "pitch", "velocity"],
      "properties": {
        "beat": {"type": "number", "minimum": 0},
        "duration": {"type": "number", "exclusiveMinimum": 0},
        "pitch": {"type": "integer", "minimum": 0, "maximum": 127},
        "velocity": {"type": "integer", "minimum": 1, "maximum": 127}
      }
    },
    "cc": {
      "type": "object", "additionalProperties": false,
      "required": ["beat", "controller", "value"],
      "properties": {
        "beat": {"type": "number", "minimum": 0},
        "controller": {"type": "integer", "minimum": 0, "maximum": 127},
        "value": {"type": "integer", "minimum": 0, "maximum": 127}
      }
    },
    "region": {
      "type": "object", "additionalProperties": false,
      "required": ["section_id", "notes", "cc"],
      "properties": {
        "section_id": {"type": "string", "minLength": 1, "maxLength": 48},
        "notes": {"type": "array", "maxItems": 2048, "items": {"$ref": "#/$defs/note"}},
        "cc": {"type": "array", "maxItems": 1024, "items": {"$ref": "#/$defs/cc"}}
      }
    },
    "track": {
      "type": "object", "additionalProperties": false,
      "required": ["id", "name", "role", "register", "instrument_hint", "regions"],
      "properties": {
        "id": {"type": "string", "pattern": "^[a-z0-9][a-z0-9_-]{0,47}$"},
        "name": {"type": "string", "minLength": 1, "maxLength": 80},
        "role": {"type": "string", "minLength": 1, "maxLength": 80},
        "register": {"$ref": "#/$defs/register"},
        "instrument_hint": {"type": "string", "minLength": 1, "maxLength": 120},
        "regions": {"type": "array", "maxItems": 48, "items": {"$ref": "#/$defs/region"}}
      }
    }
  }
}

